import { render, screen, fireEvent } from '@testing-library/react'
import { describe, it, expect } from 'vitest'
import UserProfileCard from './UserProfileCard'

describe('UserProfileCard', () => {
  it('displays the user name and toggles follow status', async () => {
    const user = { id: '1', name: 'Ada Lovelace', isFollowing: false }
    render(<UserProfileCard user={user} onToggleFollow={vi.fn()} />)

    expect(screen.getByText('Ada Lovelace')).toBeDefined()
    expect(screen.getByRole('button', { name: /follow/i })).toBeDefined()

    fireEvent.click(screen.getByRole('button', { name: /follow/i }))
    expect(screen.getByRole('button', { name: /following/i })).toBeDefined()
  })
})

import { render, screen, waitFor } from '@testing-library/react'
import { describe, it, expect, vi } from 'vitest'
import SearchPage from './SearchPage'

// The API client is a real module, not a mock.
vi.mock('./api', async () => {
  const actual = await vi.importActual<typeof import('./api')>('./api')
  return { ...actual, searchUsers: vi.fn() }
})

describe('SearchPage integration', () => {
  it('shows results after typing and loading completes', async () => {
    const { searchUsers } = await import('./api')
    vi.mocked(searchUsers).mockResolvedValue([
      { id: '1', name: 'Alan Turing' },
    ])

    render(<SearchPage />)

    const input = screen.getByPlaceholderText('Search users...')
    fireEvent.change(input, { target: { value: 'alan' } })

    expect(screen.getByText(/loading/i)).toBeDefined()

    await waitFor(() =>
      expect(screen.getByText('Alan Turing')).toBeDefined()
    )
  })
})
